import com.tngtech.archunit.lang.ArchRule;

@AnalyzeClasses(packages = "com.example.payment", importOptions = ImportOption.DoNotIncludeTests.class)
class LayerDependencyTest {

  private static final String DOMAIN = "com.example.payment.domain..";
  private static final String APPLICATION = "com.example.payment.application..";
  private static final String INFRASTRUCTURE = "com.example.payment.infrastructure..";

  private static final String[] TECHNICAL = {
    "org.springframework..", "com.fasterxml..", "jakarta..", "javax..",
    "java.io..", "java.nio..", "java.net..", "java.sql.."
  };

  @ArchTest
  static final ArchRule layers = layeredArchitecture()
      .consideringOnlyDependenciesInLayers()
      .layer("Domain").definedBy(DOMAIN)
      .layer("Application").definedBy(APPLICATION)
      .layer("Infrastructure").definedBy(INFRASTRUCTURE)
      .whereLayer("Domain").mayOnlyBeAccessedByLayers("Application", "Infrastructure")
      .whereLayer("Application").mayOnlyBeAccessedByLayers("Infrastructure")
      .whereLayer("Infrastructure").mayNotBeAccessedByAnyLayer();

  @ArchTest
  static final ArchRule domainIsFreeOfTechnicalDetails = noClasses()
      .that().resideInAPackage(DOMAIN)
      .should().dependOnClassesThat().resideInAnyPackage(TECHNICAL);

  @ArchTest
  static final ArchRule applicationIsFreeOfTechnicalDetails = noClasses()
      .that().resideInAPackage(APPLICATION)
      .should().dependOnClassesThat().resideInAnyPackage(TECHNICAL);
}
